#!/usr/bin/env bash
# The terminal sessions quoted in lesson 22 of azure-operations, as a script that
# produces them. Its output is not committed; every transcript was copied from it.
#
#   bash lab.sh student && bash lab.sh tools   # once
#   bash captures.sh
#
# WorkerHours is generated by the lesson's usage.kql and says so. The hourly
# rate and the discounts are round illustrative figures the lesson declares:
# Microsoft's price list was out of reach from the recording machine.

HERE=$(cd "$(dirname "$0")" && pwd)
# shellcheck source=../../capture.sh
. "$HERE/../../capture.sh"
student_env
kusto_up && kusto_db
kusto_load le-rdzwkma1/sizing.md:usage.kql
cd "$HOME/azure/kusto" || exit 1

block shape
kq 'WorkerHours | summarize hours = count(), min = min(Instances), p10 = percentile(Instances, 10), median = percentile(Instances, 50), max = max(Instances), avg = round(avg(Instances), 2)'
kq 'WorkerHours | summarize hours = count() by Instances | order by Instances asc'

put commit.kql <<'KQL'
// commit.kql: a month of the workers at three commitment sizes, with illustrative rates
let payg = 0.25;          // USD per instance-hour, pay as you go (illustrative)
let reserved = 0.16;      // USD per instance-hour under a 1-year reservation (illustrative)
WorkerHours
| extend k = 1
| join kind=inner (datatable(committed: int) [0, 2, 3, 4] | extend k = 1) on k
| extend covered = min_of(Instances, committed), uncovered = max_of(Instances - committed, 0)
| summarize used_reserved_hours = sum(covered), payg_hours = sum(uncovered), hours = count() by committed
| extend cost = round(committed * hours * reserved + payg_hours * payg, 2),
         unused_pct = round(100.0 * (committed * hours - used_reserved_hours) / max_of(committed * hours, 1), 1)
| project committed, cost, unused_pct
| order by committed asc
KQL
block commit
run 'python3 kql.py < commit.kql'
lab_down
